import math
from qiskit import QuantumCircuit

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int],
                 ancilla_qubits: list[int]) -> None:
    # constants
    a = [7, 10, 5, 3, 9]
    n_anc = len(ancilla_qubits)  # 6

    # angle for adding a single bit j (j=0 is LSB)
    def angle(j):
        # 2π * 2^j / 64 = π / 2**(5-j)
        return math.pi / (2 ** (5 - j))

    # Quantum Fourier Transform (and its inverse) on a list of qubits
    # No final swaps (standard QFT without bit-reversal)
    def qft(qc, qubits, inv=False):
        n = len(qubits)
        if not inv:
            # forward QFT
            for i in range(n):
                qc.h(qubits[i])
                for k in range(i + 1, n):
                    qc.cp(math.pi / (2 ** (k - i)), qubits[k], qubits[i])
            # no swaps
        else:
            # inverse QFT
            for i in range(n - 1, -1, -1):
                for k in range(i + 1, n):
                    qc.cp(-math.pi / (2 ** (k - i)), qubits[k], qubits[i])
                qc.h(qubits[i])

    # ------- compute sum into ancilla register ----------
    qft(qc, ancilla_qubits, inv=False)
    for i, p_q in enumerate(problem_qubits):
        val = a[i]
        for j in range(6):
            if (val >> j) & 1:
                # QFT without swaps reverses qubit order: use reversed index
                qc.cp(angle(j), p_q, ancilla_qubits[5 - j])
    qft(qc, ancilla_qubits, inv=True)

    # ------- apply phase when sum == 16 ----------
    # 16 = binary 010000 -> reversed (due to no-swap QFT) becomes 000010
    # So the single 1 appears at ancilla_qubits[4] (0-indexed from LSB)
    # Flip all others (indices 0,1,2,3,5) to 1, then multi-controlled phase
    for idx in [0, 1, 2, 3, 5]:
        qc.x(ancilla_qubits[idx])
    qc.mcp(math.pi,
           [ancilla_qubits[i] for i in [0, 1, 2, 3, 5]],
           ancilla_qubits[4])
    for idx in [0, 1, 2, 3, 5]:
        qc.x(ancilla_qubits[idx])

    # ------- uncompute sum (mirror) ----------
    qft(qc, ancilla_qubits, inv=False)
    for i, p_q in enumerate(problem_qubits):
        val = a[i]
        for j in range(6):
            if (val >> j) & 1:
                qc.cp(-angle(j), p_q, ancilla_qubits[5 - j])
    qft(qc, ancilla_qubits, inv=True)
